@import "@fontsource-variable/host-grotesk";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/600.css";

/* Light (faithful): white page, #151515 ink, five pale tinted surfaces, bank green
   (#29735c) for marks and active states, pale mint (#bae0cf) for highlights. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.196 0 0);
  --card: oklch(0.972 0.003 39);
  --card-foreground: oklch(0.196 0 0);
  --popover: oklch(0.976 0.004 337);
  --popover-foreground: oklch(0.196 0 0);
  --primary: oklch(0.196 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.973 0.009 206);
  --secondary-foreground: oklch(0.196 0 0);
  --muted: oklch(0.976 0.003 85);
  --muted-foreground: oklch(0.196 0 0 / 62%);
  --accent: oklch(0.974 0.011 168);
  --accent-foreground: oklch(0.428 0.066 172);
  --destructive: oklch(0.56 0.19 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.196 0 0 / 14%);
  --input: oklch(0.894 0 0);
  --ring: oklch(0.503 0.082 169);
  --highlight: oklch(0.503 0.082 169);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.875 0.046 166);
  --chart-1: oklch(0.503 0.082 169);
  --chart-2: oklch(0.875 0.046 166);
  --chart-3: oklch(0.232 0.03 177);
  --chart-4: oklch(0.41 0.051 227);
  --chart-5: oklch(0.92 0.02 60);
  --sidebar: oklch(0.976 0.003 85);
  --sidebar-foreground: oklch(0.196 0 0);
  --sidebar-primary: oklch(0.196 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.974 0.011 168);
  --sidebar-accent-foreground: oklch(0.428 0.066 172);
  --sidebar-border: oklch(0.196 0 0 / 12%);
  --sidebar-ring: oklch(0.503 0.082 169);

  --typeface-body: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 77.5rem;
  --page-gutter: 1.25rem;
  --section-y: 3.75rem;
}

/* Dark sibling: the footer's forest green (#0c221d) as the page, panels a step or two
   lighter, white text at full and 60%, pale mint buttons with ink text. */
.dark {
  --background: oklch(0.232 0.03 177);
  --foreground: oklch(1 0 0);
  --card: oklch(0.277 0.036 175);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.3 0.036 178);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.875 0.046 166);
  --primary-foreground: oklch(0.196 0 0);
  --secondary: oklch(0.29 0.034 190);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.262 0.033 176);
  --muted-foreground: oklch(1 0 0 / 62%);
  --accent: oklch(0.321 0.041 175);
  --accent-foreground: oklch(0.875 0.046 166);
  --destructive: oklch(0.66 0.18 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 20%);
  --input: oklch(1 0 0 / 24%);
  --ring: oklch(0.875 0.046 166);
  --highlight: oklch(0.74 0.09 167);
  --highlight-foreground: oklch(0.196 0 0);
  --glow: oklch(0.875 0.046 166 / 85%);
  --chart-1: oklch(0.74 0.09 167);
  --chart-2: oklch(0.875 0.046 166);
  --chart-3: oklch(0.5 0.06 175);
  --chart-4: oklch(0.7 0.06 227);
  --chart-5: oklch(0.85 0.03 60);
  --sidebar: oklch(0.262 0.033 176);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.875 0.046 166);
  --sidebar-primary-foreground: oklch(0.196 0 0);
  --sidebar-accent: oklch(0.321 0.041 175);
  --sidebar-accent-foreground: oklch(0.875 0.046 166);
  --sidebar-border: oklch(1 0 0 / 16%);
  --sidebar-ring: oklch(0.875 0.046 166);
}
